css:
@property --x {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 33.3%;
}

.wrapper {
  --size: 140px;
  --ring-width: 7px;
  --font-size: 1.5em;

  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--size);
  height: var(--size);
  padding: 0;
  border: none;
  border-radius: 50%;
  background: linear-gradient(#0000, #0002, #0000);
  cursor: pointer;
  filter: drop-shadow(0 -4px 6px #0003);
}

.wrapper .lens {
  position: absolute;
  inset: var(--ring-width);
  border-radius: 50%;
  background: radial-gradient(circle at 65% 65%, #0000 50%, #ffffff10 52%),
    radial-gradient(circle at 25% 25%, #0005 20%, #0000 100%);
  mix-blend-mode: color-dodge;
}

.wrapper .aperture {
  pointer-events: none;
  position: absolute;
  width: calc(var(--size) * 4);
  height: calc(var(--size) * 4);
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  -webkit-mask-image: radial-gradient(
    circle calc(var(--size) / 2) at center,
    #000 0,
    #000 calc(var(--size) / 2 - 1px),
    #0000 calc(var(--size) / 2)
  );
  mask-image: radial-gradient(
    circle calc(var(--size) / 2) at center,
    #000 0,
    #000 calc(var(--size) / 2 - 1px),
    #0000 calc(var(--size) / 2)
  );
}

.wrapper .shutter-area {
  position: absolute;
  width: var(--size);
  height: var(--size);
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.wrapper .shutter-instance {
  pointer-events: none;
  position: absolute;
  inset: 0;
  filter: drop-shadow(0 0 2px #000);
}

.wrapper .shutter {
  --pivot-y: 137%;
  --x: 33.3%;

  pointer-events: none;
  position: absolute;
  width: 100%;
  height: 100%;
  top: calc(50% - var(--pivot-y));
  transform-origin: 50% var(--pivot-y);
  transform: rotate(calc(var(--i) * 45deg));

  background-color: #333;
  -webkit-mask-image: linear-gradient(45deg, #000 var(--x), #0000 var(--x));
  mask-image: linear-gradient(45deg, #000 var(--x), #0000 var(--x));
  transition:
    top 0.15s ease,
    transform-origin 0.15s ease,
    --x 0.15s ease;
}

.wrapper .text {
  position: relative;
  z-index: -1;
  pointer-events: none;
  font-family: sans-serif;
  color: #e8e8e8;
  font-size: var(--font-size);
  font-weight: 600;
  text-shadow: 0 0 16px #0007;
  opacity: 0.55;
  transition: opacity 0.25s ease;
}

.wrapper .ring {
  pointer-events: none;
  position: absolute;
  z-index: 3;
  inset: 0;
  border-radius: inherit;
  background: conic-gradient(from 40deg, #888, #fff, #777, #fff, #888);
  -webkit-mask-image: radial-gradient(
    circle at center,
    #0000 calc(0.5 * var(--size) - var(--ring-width)),
    #000 calc(0.5 * var(--size) - var(--ring-width) + 1px)
  );
  mask-image: radial-gradient(
    circle at center,
    #0000 calc(0.5 * var(--size) - var(--ring-width)),
    #000 calc(0.5 * var(--size) - var(--ring-width) + 1px)
  );
}

.wrapper:hover .shutter {
  --pivot-y: 133%;
  --x: 32%;
}
.wrapper:active .shutter {
  --pivot-y: 101.3%;
  --x: 25.3%;
}
.wrapper:hover .text {
  opacity: 1;
}
